module adder_bcd (
    input  [3:0] A,
    input  [3:0] B,
    input  Cin,
    output [3:0] Sum,
    output Cout
);

wire [4:0] sum_raw;
wire [4:0] sum_bcd;
wire correction;

assign sum_raw = A + B + Cin;
assign correction = sum_raw > 5'd9;
assign sum_bcd = correction ? (sum_raw + 5'd6) : sum_raw;

assign Sum = sum_bcd[3:0];
assign Cout = correction;

endmodule

